from pathlib import Path
from fractions import Fraction as Q
import json,hashlib,itertools as it,resource,time,sys,ast
sys.path.insert(0,'code')
from classification_cubic_scroll_abelian_review import add,scale,mul,diff,parse,monomials
from classification_cubic_scroll_four_sources_review import substitute
start=time.monotonic();resource.setrlimit(resource.RLIMIT_CPU,(110,115));resource.setrlimit(resource.RLIMIT_AS,(2048*1024**2,)*2)
jobpath=Path('research/classification/jobs/plane_m3_invariant_hyperplane_separate_review.json');job=json.load(jobpath.open());N=0
for x in job['exact_inputs_and_hashes']:assert hashlib.sha256(Path(x['path']).read_bytes()).hexdigest()==x['sha256'],x['path']
def ck(a,b,label):
 global N
 assert a==b,label
 N+=1
def read(path):return json.load(open(path))
def record(source,typ,alpha):
 base=next(r for r in source['cases']if r['type']==typ)
 if alpha=='whole':return base
 return next(r for r in base.get('all_exceptional_sources',base.get('all_exceptional_roots',[]))if r['alpha']==alpha)
def allzero(rows):return all(x=='0' for row in rows for x in row)
def normalfactor(P0,index):
 names=['tau','a','b','c','z','w'];bad=[]
 for pair,text in P0.items():
  ij=tuple(map(int,pair.strip('()').split(',')))
  if index in ij:bad.extend(ex for ex,co in parse(text,names).items()if not ex[1+index])
 return not bad
sources={
 'constant':read('reports/CLASSIFICATION_PLANE_NONREDUCED_M3_CONSTANT_ROOTS_20261107.json'),
 'double':read('reports/CLASSIFICATION_PLANE_NONREDUCED_M3_MOVING_DOUBLE_20261107.json'),
 'simple':read('reports/CLASSIFICATION_PLANE_NONREDUCED_M3_MOVING_SIMPLE_20261107.json')}
# Whole30 P1 and FULL9 P2 definitions are independently fixed before reading their kernels.
source1names=[f'l{i}'for i in range(9)]+[f'n{i}'for i in range(9)]+[f'd{i}'for i in range(3)]+[f'b{i}'for i in range(3)]+[f'e{i}'for i in range(3)]+[f'c{i}'for i in range(3)]
coords=['a','b','c','z','w'];names=source1names+coords
expected={};pairs=list(it.combinations(range(5),2))
for ij in pairs:expected[str(ij)]='0'
for j,ij in enumerate([(0,1),(0,2),(1,2)]):
 expected[str(ij)]='+'.join(f'{coords[k]}*(l{3*j+k}*z+n{3*j+k}*w)'for k in range(3))
for i in range(3):
 expected[str((i,3))]=f'b{i}*z*w+c{i}*w**2';expected[str((i,4))]=f'd{i}*z**2+e{i}*z*w'
for ij in expected:ck(parse(sources['constant']['full_source1'][ij],names),parse(expected[ij],names),'all30 original source1 ordering')
source2=sources['constant']['full_source2']
for ij,text in source2.items():
 if 3 in ast.literal_eval(ij) or 4 in ast.literal_eval(ij):ck(text,'0','FULL9P2 no normalcolumns')
rowresults=[]
shorts=[('constant','reports/CLASSIFICATION_PLANE_M3_CONSTANT_CEXACT_INVARIANT_ROWS_20261108.json'),('double','reports/CLASSIFICATION_PLANE_M3_MOVING_DOUBLE_WEAK_INVARIANT_ROWS_20261108.json'),('simple','reports/CLASSIFICATION_PLANE_M3_MOVING_SIMPLE_INITIAL_INVARIANT_ROWS_20261108.json')]
for kind,path in shorts:
 short=read(path);base=sources[kind]
 for case in short['cases']:
  r=record(base,case['type'],case['alpha']);K=r['weight1_certificate']['complete_kernel'];assert len(K)==30
  Crows=K[27:30];Drows=K[18:21]
  ck(Crows,case.get('all_three_C_rows',case.get('all3_C_rows')),'original fullkernel C readback')
  if kind=='constant':ck(Drows,case['all_three_D_rows'],'original fullkernel D readback')
  C0=allzero(Crows);D0=allzero(Drows);P0=r.get('full150_P0',record(base,case['type'],'whole')['full150_P0'])
  cf=C0 and normalfactor(P0,3);df=D0 and normalfactor(P0,4)
  if kind=='constant':assert cf or df
  elif kind=='double':assert cf or(case['type']=='REPEATED_LINE_OTHER'and case['alpha']=='-8/3')
  else:assert cf or(case['type']=='DEG1_HB_CA_OTHER'and case['alpha']=='-11/3')
  rowresults.append({'kind':kind,'type':case['type'],'alpha':case['alpha'],'all_C_zero':C0,'all_D_zero':D0,'z_row_factor':cf,'w_row_factor':df})
 # Explicitly compare selected wholeparameter families with their COMPLETE saved walllists.
 for typ in {c['type']for c in short['cases']}:
  basecase=record(base,typ,'whole');oldwalls=basecase.get('all_exceptional_sources',basecase.get('all_exceptional_roots',[]));oldset={q['alpha']for q in oldwalls};newset={q['alpha']for q in short['cases']if q['type']==typ and q['alpha']!='whole'}
  ck(newset,oldset,'all complex source walls retained')
cdep=read('reports/CLASSIFICATION_PLANE_DOUBLE_LINE_M3_SQUAREFREE_REPLAY_20261107.json')['cases'][15]
assert cdep['type']=='C_DEPENDENT_A2_G2'
cdcert=read('reports/CLASSIFICATION_PLANE_DOUBLE_LINE_M3_CDEPENDENT_WHOLE_FACTOR_20261108.json')
K=cdep['weight1_certificate']['complete_kernel'];ck(K[27:30],cdcert['literal_bad_rows'],'cdependent rows');assert allzero(K[27:30])and normalfactor(cdep['full150_P0'],3)
# One batch for the two already-selected critical complete sources, no new operator/rank.
def matrix(data,names):
 P=[[{}for j in range(5)]for i in range(5)]
 for key,text in data.items():
  i,j=map(int,key.strip('()').split(','));P[i][j]=parse(text,names);P[j][i]=scale(P[i][j],-1)
 return P
def ja(P,np):
 jj={}
 for tri in it.combinations(range(5),3):
  jj[tri]=add(*(mul(P[i][ell],diff(P[j][k],np+ell))for i,j,k in [tri,(tri[1],tri[2],tri[0]),(tri[2],tri[0],tri[1])]for ell in range(5)))
 rows=[]
 for quad in it.combinations(range(5),4):
  value=add(*(scale(mul(parse(coords[quad[i]],pnames+coords),jj[quad[:i]+quad[i+1:]]),(-1)**i)for i in range(4)))
  rows.extend({ex[:np]+(0,)*5:co for ex,co in value.items()if ex[np:]==physical}for physical in monomials(5,4))
 return rows
critresults=[];pnames=[f'p{i}'for i in range(9)];names=pnames+coords;np=9;n=len(names);zero=(0,)*n
for kind,path,factor in [('double','reports/CLASSIFICATION_PLANE_M3_MOVING_DOUBLE_CRITICAL_20261108.json',-2),('simple','reports/CLASSIFICATION_PLANE_M3_MOVING_SIMPLE_CRITICAL_20261108.json',1)]:
 crit=read(path);old=record(sources[kind],crit['type'],crit['alpha']);K=old['weight1_certificate']['complete_kernel'];ck(K,crit['all30by9_saved_necessary_kernel'],'critical original complete30x9')
 P0=matrix(crit['complete_P0'],names);savedP1=matrix(crit['complete_P1'],names);P1=[[{}for j in range(5)]for i in range(5)]
 for ij,text in expected.items():
  data=parse(text,source1names+coords)
  images=[add(*(scale(parse(pnames[j],names),Q(K[i][j]))for j in range(9)))for i in range(30)]+[parse(t,names)for t in coords]
  i,j=ast.literal_eval(ij);P1[i][j]=substitute(data,images,n);P1[j][i]=scale(P1[i][j],-1);ck(P1[i][j],savedP1[i][j],'critical P1 full30 recipe')
 oldP0=matrix(old['full150_P0'],names)
 for i,j in pairs:ck(P0[i][j],oldP0[i][j],'critical original P0')
 parts=[parse(t,names)for t in crit['unique_inhomogeneous_FULL9_P2_particular']]
 P2=[[{}for j in range(5)]for i in range(5)];normalmons=[parse(t,names)for t in ['z**2','z*w','w**2']]
 for k,(i,j)in enumerate([(0,1),(0,2),(1,2)]):
  P2[i][j]=add(*(mul(parts[3*k+l],normalmons[l])for l in range(3)));P2[j][i]=scale(P2[i][j],-1)
 # Existing M2 certificate provides uniqueness; check its ORIGINAL selected equations, not just an asserted particular.
 cert=old['weight2_certificate'];ck(cert['minor_rows'],crit['same_existing_M2_minor_rows'],'same9rows');ck(cert['minor_columns'],crit['same_existing_M2_minor_columns'],'same9cols');ck(cert['minor_determinant'],crit['same_existing_M2_minor_determinant'],'same nonzero oldminor');assert cert['rank']==9 and cert['nullity']==0 and Q(cert['minor_determinant'])
 B=old['full350_weight2_operator'];C=ja(P1,np);weight2=[add(C[i],*(scale(parts[j],Q(B[i][j]))for j in range(9)))for i in range(350)]
 for i in cert['minor_rows']:ck(weight2[i],{},'selected uniqueP2 equation')
 for value,text in zip(weight2,crit['all350_weight2_compatibilities']):ck(value,parse(text,names),'all350 weight2 compatibility')
 P=[[add(P0[i][j],P1[i][j],P2[i][j])for j in range(5)]for i in range(5)];J=ja(P,np)
 for value,text in zip(J,crit['all350_original_Jacobi_after_elimination']):ck(value,parse(text,names),'all350 originalcyclic')
 target=parse(f'{factor}*p8**2',names);ck(J[54],target,'critical row54');ck(J[279],target,'critical row279')
 p8index=8
 for i,j in pairs:
  if 3 in (i,j):
   ck({ex:co for ex,co in P[i][j].items()if not ex[p8index]and not ex[np+3]}, {},'p8zero forceswhole zrow factor')
 D={}
 for omit in range(5):
  i,j,k,l=[q for q in range(5)if q!=omit]
  pf=add(mul(P[i][j],P[k][l]),scale(mul(P[i][k],P[j][l]),-1),mul(P[i][l],P[j][k]))
  D=add(D,scale(mul(parse(coords[omit],names),pf),(-1)**omit))
 ck(D,parse(crit['full_actual_D'],names),'critical full actualD')
 D8={ex:co for ex,co in D.items()if not ex[p8index]};ck(D8,parse(crit['full_actual_D_at_p8_zero'],names),'D atp8zero');assert all(ex[np+3]for ex in D8)
 critresults.append({'kind':kind,'type':crit['type'],'alpha':crit['alpha'],'original_complete9_P1_verified':True,'FULL9_P2_unique_inhomogeneous_particular_verified':True,'same_old_nonzero9minor_reused':True,'all350_compatibilities_and_original_rows_match':True,'row54_and279':str(factor)+'*p8**2','full_actual_Pfaffian_match':True,'reduced_p8_zero_forces_actual_zfactor':True})
result={'task_id':'E_reduced_nonnormal','all_passed':True,'scope':'Whole new invariant-hyperplane closures forconstantCexact, cdependentK1, movingdoubleall, movingsimpleinitial; old canonicalHB0tau0/HA1tau2over15 parent obligations retained','no_producer_import_or_CAS':True,'no_new_M1_rank_operator_point_or_profile':True,'full_source1_30_and_source2_9_order_independently_verified':True,'all_generic_and_complex_wall_normal_rows':rowresults,'cdependent_all10kernel_Crows_zero':True,'two_critical_full_original_checks':critresults,'constant00_whole_aggregate_to_eight_essential3_components_hand_review':True,'movingdouble_whole11_empty_hand_review':True,'movingsimple37plus22_initial_reduction_leaves_two_canonical_modules':True,'new_component_count':0,'identity_count':N,'input_sha256':{r['path']:hashlib.sha256(Path(r['path']).read_bytes()).hexdigest()for r in job['exact_inputs_and_hashes']},'inline_source':job['inline_source'],'seconds':time.monotonic()-start,'maxrss_kb':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}
out=Path('reports/CLASSIFICATION_PLANE_M3_INVARIANT_HYPERPLANE_SEPARATE_REVIEW_20261108.json')
with out.open('x')as f:json.dump(result,f,indent=2);f.write('\n')
print(json.dumps({k:result[k]for k in ['all_passed','identity_count','seconds','maxrss_kb']}))
